import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname } from 'node:path';

export class ValidationError extends Error {}

export function createStore(filePath) {
  let books = null;
  // Writes are chained so two quick requests never interleave their file writes.
  let pending = Promise.resolve();

  async function load() {
    if (books) return books;
    try {
      const raw = await readFile(filePath, 'utf8');
      books = JSON.parse(raw);
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      books = [];
    }
    return books;
  }

  function save() {
    pending = pending.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      // Write to a temp file first so a crash mid-write can't corrupt the real one.
      const tmp = `${filePath}.tmp`;
      await writeFile(tmp, JSON.stringify(books, null, 2) + '\n');
      await rename(tmp, filePath);
    });
    return pending;
  }

  return {
    async all() {
      return [...(await load())];
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes = '' }) {
      title = String(title ?? '').trim();
      author = String(author ?? '').trim();
      notes = String(notes ?? '').trim();
      if (!title) throw new ValidationError('Title is required');
      if (!author) throw new ValidationError('Author is required');

      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        startedAt: new Date().toISOString(),
        finishedAt: null,
      };
      (await load()).push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = await this.get(id);
      if (!book) return null;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },

    async updateNotes(id, notes) {
      const book = await this.get(id);
      if (!book) return null;
      book.notes = String(notes ?? '').trim();
      await save();
      return book;
    },
  };
}

