export function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

const e = escapeHtml;

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${e(title)}</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
  h1, h2 { margin-bottom: 0.5rem; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: 0.5rem 0; border-bottom: 1px solid #8884; display: flex; justify-content: space-between; gap: 1rem; align-items: baseline; }
  .author, .meta { opacity: 0.7; font-size: 0.9em; }
  .empty { opacity: 0.7; font-style: italic; }
  form.inline { display: inline; }
  label { display: block; margin-top: 0.75rem; font-weight: 600; }
  input, textarea { width: 100%; box-sizing: border-box; padding: 0.4rem; font: inherit; margin-top: 0.25rem; }
  textarea { min-height: 6rem; }
  button { margin-top: 0.75rem; padding: 0.4rem 0.9rem; font: inherit; cursor: pointer; }
  .notes { white-space: pre-wrap; }
  .error { color: #c33; }
  .share { font-size: 0.9em; margin-top: 2rem; }
  .share code { user-select: all; }
</style>
</head>
<body>
<h1><a href="/">My Books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const action = book.finishedAt
    ? `<span class="meta">Finished ${e(formatDate(book.finishedAt))}</span>`
    : `<form class="inline" method="post" action="/books/${e(book.id)}/finish">
         <button type="submit">Mark finished</button>
       </form>`;
  return `<li>
    <span><a href="/books/${e(book.id)}">${e(book.title)}</a> <span class="author">by ${e(book.author)}</span></span>
    ${action}
  </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${e(emptyText)}</p>`;
  return `<ul class="books">${books.map(bookItem).join('')}</ul>`;
}

export function indexPage(books, { error = '', values = {} } = {}) {
  const reading = books.filter((b) => !b.finishedAt);
  const finished = books
    .filter((b) => b.finishedAt)
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return layout(
    'My Books',
    `
<section>
  <h2>Currently reading</h2>
  ${bookList(reading, 'Nothing on the go right now.')}
</section>

<section>
  <h2>Finished</h2>
  ${bookList(finished, 'No finished books yet.')}
</section>

<section>
  <h2>Add a book</h2>
  ${error ? `<p class="error">${e(error)}</p>` : ''}
  <form method="post" action="/books">
    <label>Title <input name="title" required value="${e(values.title ?? '')}"></label>
    <label>Author <input name="author" required value="${e(values.author ?? '')}"></label>
    <label>Notes <textarea name="notes">${e(values.notes ?? '')}</textarea></label>
    <button type="submit">Add book</button>
  </form>
</section>`,
  );
}

export function bookPage(book, shareUrl) {
  const status = book.finishedAt
    ? `<p class="meta">Started ${e(formatDate(book.startedAt))} · Finished ${e(formatDate(book.finishedAt))}</p>`
    : `<p class="meta">Started ${e(formatDate(book.startedAt))} · Currently reading</p>
       <form method="post" action="/books/${e(book.id)}/finish">
         <button type="submit">Mark finished</button>
       </form>`;

  return layout(
    `${book.title} – My Books`,
    `
<p><a href="/">← All books</a></p>
<h2>${e(book.title)}</h2>
<p class="author">by ${e(book.author)}</p>
${status}

<h3>Notes</h3>
<form method="post" action="/books/${e(book.id)}/notes">
  <textarea name="notes" aria-label="Notes">${e(book.notes)}</textarea>
  <button type="submit">Save notes</button>
</form>

<p class="share">Share this book: <code>${e(shareUrl)}</code></p>`,
  );
}

export function notFoundPage() {
  return layout('Not found – My Books', `<h2>Book not found</h2><p><a href="/">← All books</a></p>`);
}

