import { createServer } from 'node:http';
import { ValidationError } from './store.js';
import { bookPage, indexPage, notFoundPage } from './views.js';

const MAX_BODY = 64 * 1024;

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.setEncoding('utf8');
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > MAX_BODY) {
        reject(new Error('Request body too large'));
        req.destroy();
      }
    });
    req.on('end', () => resolve(Object.fromEntries(new URLSearchParams(body))));
    req.on('error', reject);
  });
}

function html(res, status, body) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

export function createApp(store) {
  return createServer(async (req, res) => {
    try {
      const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
      const { pathname } = url;
      const bookMatch = pathname.match(/^\/books\/([^/]+)(?:\/(finish|notes))?$/);

      if (req.method === 'GET' && pathname === '/') {
        return html(res, 200, indexPage(await store.all()));
      }

      if (req.method === 'POST' && pathname === '/books') {
        const form = await readForm(req);
        try {
          const book = await store.add(form);
          return redirect(res, `/books/${book.id}`);
        } catch (err) {
          if (!(err instanceof ValidationError)) throw err;
          return html(res, 400, indexPage(await store.all(), { error: err.message, values: form }));
        }
      }

      if (bookMatch) {
        const [, id, action] = bookMatch;

        if (req.method === 'GET' && !action) {
          const book = await store.get(id);
          if (!book) return html(res, 404, notFoundPage());
          return html(res, 200, bookPage(book, `${url.origin}/books/${book.id}`));
        }

        if (req.method === 'POST' && action === 'finish') {
          const book = await store.finish(id);
          if (!book) return html(res, 404, notFoundPage());
          return redirect(res, req.headers.referer?.endsWith(`/books/${id}`) ? `/books/${id}` : '/');
        }

        if (req.method === 'POST' && action === 'notes') {
          const form = await readForm(req);
          const book = await store.updateNotes(id, form.notes);
          if (!book) return html(res, 404, notFoundPage());
          return redirect(res, `/books/${id}`);
        }
      }

      return html(res, 404, notFoundPage());
    } catch (err) {
      console.error(err);
      if (!res.headersSent) html(res, 500, '<h1>Something went wrong</h1>');
      else res.end();
    }
  });
}

