  file = join(dir, 'nested', 'books.json');
});

afterEach(() => rm(dir, { recursive: true, force: true }));

describe('store', () => {
  it('starts empty when the file does not exist', async () => {
    expect(await createStore(file).all()).toEqual([]);
  });

  it('adds a book and persists it to the JSON file', async () => {
    const store = createStore(file);
    const book = await store.add({ title: ' Dune ', author: 'Frank Herbert', notes: 'Sci-fi' });

    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'Sci-fi', finishedAt: null });
    expect(book.id).toBeTruthy();

    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toEqual([book]);
  });

  it('reloads books from disk in a fresh store', async () => {
    const first = createStore(file);
    const a = await first.add({ title: 'A', author: 'X' });
    await first.finish(a.id);

    const second = createStore(file);
    expect(await second.get(a.id)).toMatchObject({ title: 'A', finishedAt: expect.any(String) });
  });

  it('rejects books without a title or author', async () => {
    const store = createStore(file);
    await expect(store.add({ title: '', author: 'X' })).rejects.toBeInstanceOf(ValidationError);
    await expect(store.add({ title: 'A', author: '   ' })).rejects.toBeInstanceOf(ValidationError);
    expect(await store.all()).toEqual([]);
  });

  it('marks a book finished only once', async () => {
    const store = createStore(file);
    const book = await store.add({ title: 'A', author: 'X' });

    const finished = await store.finish(book.id);
    const again = await store.finish(book.id);

    expect(finished.finishedAt).toEqual(expect.any(String));
    expect(again.finishedAt).toBe(finished.finishedAt);
  });

  it('returns null for unknown ids', async () => {
    const store = createStore(file);
    expect(await store.get('nope')).toBeNull();
    expect(await store.finish('nope')).toBeNull();
    expect(await store.updateNotes('nope', 'x')).toBeNull();
  });

  it('updates notes', async () => {
    const store = createStore(file);
    const book = await store.add({ title: 'A', author: 'X' });
    await store.updateNotes(book.id, 'Loved chapter 3');
    expect((await store.get(book.id)).notes).toBe('Loved chapter 3');
  });

  it('does not leak internal array mutations', async () => {
    const store = createStore(file);
    await store.add({ title: 'A', author: 'X' });
    (await store.all()).pop();
    expect(await store.all()).toHaveLength(1);
  });
});

