import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../lib/app.js';
import { createStore } from '../lib/store.js';

let dir;
let server;
let base;
let store;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-app-'));
  store = createStore(join(dir, 'books.json'));
  server = createApp(store);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((resolve) => server.close(resolve));
  await rm(dir, { recursive: true, force: true });
});

function post(path, fields, headers = {}) {
  return fetch(base + path, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/x-www-form-urlencoded', ...headers },
    body: new URLSearchParams(fields),
  });
}

describe('app', () => {
  it('shows currently reading and finished sections on the home page', async () => {
    const reading = await store.add({ title: 'Reading Now', author: 'A' });
    const done = await store.add({ title: 'All Done', author: 'B' });
    await store.finish(done.id);

    const html = await (await fetch(base + '/')).text();
    const readingIdx = html.indexOf('Currently reading');
    const finishedIdx = html.indexOf('<h2>Finished</h2>');

    expect(html).toContain(`href="/books/${reading.id}"`);
    expect(html).toContain(`href="/books/${done.id}"`);
    expect(html.indexOf('Reading Now')).toBeGreaterThan(readingIdx);
    expect(html.indexOf('Reading Now')).toBeLessThan(finishedIdx);
    expect(html.indexOf('All Done')).toBeGreaterThan(finishedIdx);
  });

  it('adds a book from the form and redirects to its page', async () => {
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Spice' });
    expect(res.status).toBe(303);

    const location = res.headers.get('location');
    expect(location).toMatch(/^\/books\/[0-9a-f-]+$/);

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('Dune');
    expect(page).toContain('Frank Herbert');
    expect(page).toContain('Spice');
    expect(page).toContain(`${base}${location}`); // share link
  });

  it('re-renders the form with an error when validation fails', async () => {
    const res = await post('/books', { title: '', author: 'Someone' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required');
    expect(html).toContain('value="Someone"');
  });

  it('marks a book finished from the list and redirects home', async () => {
    const book = await store.add({ title: 'A', author: 'X' });
    const res = await post(`/books/${book.id}/finish`, {}, { referer: `${base}/` });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect((await store.get(book.id)).finishedAt).toBeTruthy();
  });

  it('marks a book finished from its own page and stays there', async () => {
    const book = await store.add({ title: 'A', author: 'X' });
    const res = await post(`/books/${book.id}/finish`, {}, { referer: `${base}/books/${book.id}` });
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
  });

  it('saves notes from the book page', async () => {
    const book = await store.add({ title: 'A', author: 'X' });
    const res = await post(`/books/${book.id}/notes`, { notes: 'New thoughts' });
    expect(res.status).toBe(303);
    expect((await store.get(book.id)).notes).toBe('New thoughts');
  });

  it('escapes HTML in user content', async () => {
    await store.add({ title: '<script>alert(1)</script>', author: 'X' });
    const html = await (await fetch(base + '/')).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
  });

  it('returns 404 for unknown books and routes', async () => {
    expect((await fetch(base + '/books/nope')).status).toBe(404);
    expect((await fetch(base + '/whatever')).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
  });
});

